    static void tower(){var m=towerGame();play(m);for(UUID p:List.of(A,B)){if(p.equals(B))m.endTurn(A);int before=m.privateView(p).hand().size();m.activateStadium(p,m.clientView(p).stadium().instanceId(),m.stadiumEntrySequence());var q=m.effectCardPrompt(p);check(q.candidates().stream().allMatch(c->m.cardDefinition(c.definitionId()).battleStyles().contains(BattleStyle.SINGLE_STRIKE)),"Tower allowed non-Single Strike cost");m.submitEffectCards(p,q.resolutionId(),q.step(),List.of(q.candidates().getFirst().instanceId()));settle(m);check(m.privateView(p).hand().size()==before+1&&!m.canActivateStadium(p),"Tower cost/draw or per-player limit");}}
